// Bundled JMA tide tables, generated by scripts/build_tide_data.py.

const cache = new Map();

export function loadTide(year) {
  if (!cache.has(year)) {
    const url = new URL(`../data/tide/${year}.json`, import.meta.url);
    cache.set(year, fetch(url).then((r) => (r.ok ? r.json() : null)).catch(() => null));
  }
  return cache.get(year);
}

export async function tideFor(date, station) {
  const data = await loadTide(Number(date.slice(0, 4)));
  return data?.[station]?.[date] ?? null;
}
